async function exportHoursPdf(){
  const entries=monthEntries();if(!entries.length){toast('Aucune heure pour le mois sélectionné');return;}
  const buttons=$$('[data-export-pdf]');buttons.forEach(b=>b.disabled=true);
  try{
    const period=`${capitalize(monthNames[activeMonth.getMonth()])} ${activeMonth.getFullYear()}`;
    const pdf=buildHoursPdf(entries,state.farms,period);
    const name=`heures-lcmc-${activeMonth.getFullYear()}-${String(activeMonth.getMonth()+1).padStart(2,'0')}-${Date.now()}.pdf`;
    if(window.Capacitor?.isNativePlatform?.()){
      const fs=window.Capacitor.Plugins?.Filesystem;
      if(!fs)throw new Error('Module de fichiers absent de cet APK');
      let permission=await fs.checkPermissions();
      if(permission.publicStorage!=='granted')permission=await fs.requestPermissions();
      if(permission.publicStorage!=='granted')throw new Error('Accès aux documents refusé');
      const options={path:`LCMC/${name}`,directory:'DOCUMENTS'};
      const data=btoa(pdf);
      await fs.writeFile({...options,data,recursive:true});
      const saved=await fs.readFile(options);
      if(saved.data!==data)throw new Error('Vérification du PDF impossible');
      showFileResult(`PDF enregistré et vérifié.\nMes fichiers → Stockage interne → Documents → LCMC\n${name}`);
    }else{
      const url=URL.createObjectURL(new Blob([pdf],{type:'application/pdf'}));
      const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(url),30000);
      showFileResult('PDF demandé au navigateur. Consulte Téléchargements.');
    }
    toast('PDF prêt à imprimer');
  }catch(error){showFileResult(`Échec de l’export PDF : ${error.message}. Tes heures sont conservées.`,true);toast('Export PDF impossible');}
  finally{buttons.forEach(b=>b.disabled=false);}
}
